insert into public.card_products (
  id, release_id, slug, name, issuer, network, country_code, billing_currency,
  base_reward_type, base_reward_rate, point_value_pence, annual_fee_pence,
  redemption_label, terms_version, terms_url, comparison_status, source_checked_at,
  data_notes, valid_from, artwork_from, artwork_to, artwork_accent, active, is_demo
) values
  ('fee2f2fb-69f5-53d6-a172-1814af33b9e6', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-rewards-credit-card', 'American Express® Rewards Credit Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'points', 1, 0.45, 0, 'Membership Rewards statement-credit floor', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/rewards-credit-card/American_Express_Rewards_301_5VT_Card_Summary_Box.pdf', 'verified', '2026-09-28', 'The base value uses American Express''s official 1,000-points-to-£4.50 statement-credit option (0.45p per point). Other redemption methods can be worth more or less. Membership Rewards value varies by redemption; £0.005 is valid only for the cited official examples. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('baf9b5cc-a2af-5bfe-a47d-4e264d4dd997', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-cashback', 'Amex® Cashback Credit Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'cashback', 0, null, 2500, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/platinum-cashback-credit-card/Plat-CB-SB.pdf', 'catalog_only', '2026-09-28', 'Ongoing rewards are stated directly as cashback percentages and the annual fee is explicit. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('19f58231-7df5-5f60-9c6f-842db653adb0', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-cashback-everyday', 'Amex® Cashback Everyday Credit Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'cashback', 0, null, 0, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/platinum-cashback-everyday-credit-card/Plat-CB-everyday-SB.pdf', 'catalog_only', '2026-09-28', 'Ongoing rewards are stated directly as cashback percentages. At least £3,000 of eligible spend in the cardmembership year is required to receive cashback. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('e283cc49-4333-57e4-b254-7e7b1e1d82c4', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-british-airways', 'British Airways American Express® Credit Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'cashback', 0, null, 0, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/ba-credit-card/BACreditSummaryBox.pdf', 'catalog_only', '2026-09-28', 'Avios and the Companion Voucher do not have a single official fixed monetary value. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('da035fb1-1173-5780-873b-53801b559dfe', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-british-airways-premium-plus', 'British Airways American Express® Premium Plus Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'cashback', 0, null, 30000, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/ba-premium-plus-credit-card/BAPremiumPlusSummaryBox.pdf', 'catalog_only', '2026-09-28', 'Avios and the Companion Voucher do not have a single official fixed monetary value. The issuer announces an earn-rate change effective 7 October 2026. The 3-Avios British Airways/British Airways Holidays rate is shown only through 6 October on the official page; the post-change category rate should be rechecked on the effective date. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('4090d966-b852-53a7-af97-f2422852619c', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-marriott-bonvoy', 'Marriott Bonvoy® American Express® Credit Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'cashback', 0, null, 9500, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/marriott-credit-card/Marriott-SummaryBox.pdf', 'catalog_only', '2026-09-28', 'Marriott Bonvoy points do not have a single official fixed monetary value. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('06516fe0-4ee3-5f9e-a075-afb4d99175cb', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-nectar', 'Nectar Credit Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'points', 2, 0.5, 3000, 'Nectar points at the issuer-stated minimum redemption value', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/nectar-credit-card/NectarCard-SB.pdf', 'verified', '2026-09-28', 'The issuer states an official minimum monetary value of £0.005 per Nectar point for named partner redemptions. The advertised partner earn of at least 3 points per £1 includes points earned from presenting the separate Nectar loyalty card; it is not wholly incremental credit-card reward. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('9760d548-2c06-57b7-b0d8-7ff29b1d82b6', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-preferred-rewards-gold', 'Preferred Rewards Gold Credit Card', 'American Express UK', 'American Express', 'GB', 'GBP', 'cashback', 0, null, 19500, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/gold-credit-card/Preferred_Rewards_Gold_Credit_Card_Summary_Box.pdf', 'catalog_only', '2026-09-28', 'Membership Rewards points do not have one fixed official cash value across redemption options. The page markets gift-card value examples using ''up to''; these are not a universal fixed point value. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('4dd217fd-7529-5c8d-bf94-dd28234735bc', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amex-uk-platinum-card', 'The Platinum Card®', 'American Express UK', 'American Express', 'GB', 'GBP', 'cashback', 0, null, 65000, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://icm.aexp-static.com/Internet/internationalcardshop/en_gb/pdf/platinum-card/Platinum_Card_Summary_Box.pdf', 'catalog_only', '2026-09-28', 'Membership Rewards points do not have one fixed official cash value across redemption options. The product page describes Membership Rewards redemption options but does not state a single fixed value applicable to every point. Published foreign-purchase fee: 2.99%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('4b095b73-0366-5714-85d0-8e85b0b36f3d', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'bank-of-scotland-advance-credit-card', 'Bank of Scotland Advance Credit Card', 'Bank of Scotland', 'Mastercard', 'GB', 'GBP', 'cashback', 0, null, 0, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://www.bankofscotland.co.uk/assets/pdf/credit-cards/summary-box/bank-of-scotland-credit-card.pdf', 'catalog_only', '2026-09-28', 'Active product with no deterministic ongoing purchase reward. The generic Bank of Scotland summary box may not be specific to the Advance variant; verify card-specific pricing before production import. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking. Published foreign-purchase fee: 2.95%. FX costs are not yet included in ranking.', '2026-09-28', '#3c254f', '#7d50a2', '#ead6ff', true, false),
  ('6bc8c962-784c-5e5c-afda-c98362a336c5', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'barclaycard-avios', 'Barclaycard Avios', 'Barclaycard', 'Mastercard', 'GB', 'GBP', 'cashback', 0, null, 0, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://www.barclays.co.uk/credit-cards/avios-cards/barclaycard-avios/', 'catalog_only', '2026-09-28', 'The earn rate is exact, but the issuer does not provide a fixed pence-per-Avios value suitable for cross-card ranking. Foreign-use fee not explicit in retrieved product evidence. Voucher value and Avios value depend on redemption. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('9f7b6d53-2240-59ec-9466-203e09cf6c68', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'barclaycard-avios-plus', 'Barclaycard Avios Plus card', 'Barclaycard', 'Mastercard', 'GB', 'GBP', 'cashback', 0, null, 24000, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://www.barclays.co.uk/credit-cards/avios-cards/barclaycard-avios-plus/', 'catalog_only', '2026-09-28', 'The earn rate is exact, but the issuer does not provide a fixed pence-per-Avios value suitable for cross-card ranking. Foreign-use fee not explicit in retrieved product evidence. Voucher value and Avios value depend on redemption. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('1e9fbb5d-29f7-5614-94ee-b9588826d0c9', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'barclaycard-rewards', 'Barclaycard Rewards card', 'Barclaycard', 'Visa', 'GB', 'GBP', 'cashback', 0.25, null, 0, 'Cashback credited under the issuer reward rules', 'Official issuer material checked 2026-09-28', 'https://www.barclays.co.uk/credit-cards/reward-cards/barclays-rewards/', 'verified', '2026-09-28', 'Fixed cash value and a single published ongoing rate. No explicit annual-fee line was exposed on the product page; £0 is inferred from the representative APR having no stated account fee and should be checked against the linked summary before production import. Published foreign-purchase fee: 0%. FX costs are not yet included in ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('9424573f-b7b0-5b01-8cb9-010f47c6dc5d', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'amazon-barclaycard', 'The Amazon Barclaycard', 'Barclaycard', 'Mastercard', 'GB', 'GBP', 'cashback', 0.25, null, 0, 'Amazon rewards redeemed in £5 Amazon Gift Card increments', 'Official issuer material checked 2026-09-28', 'https://www.barclays.co.uk/credit-cards/reward-cards/the-amazon-barclaycard/', 'verified', '2026-09-28', 'The steady-state Amazon and other-purchase reward rates have direct cash-equivalent gift-card values. Prime-event 2% rewards are event-specific and must be ingested as dated offers, not an ongoing rule. Foreign-use fee was not explicit in the retrieved product evidence. Official page does not plainly name the scheme network in the retrieved text; network should be confirmed from the summary PDF before import. 3 introductory or account-specific promotions were recorded in research but excluded from ongoing checkout ranking.', '2026-09-28', '#292a31', '#5b5e6b', '#e6e7eb', true, false),
  ('cb641484-6fce-56ba-87d9-f6376219cc6c', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'capital-one-balance-transfer', 'Capital One Balance Transfer Card', 'Capital One (Europe) plc', 'Not stated', 'GB', 'GBP', 'cashback', 0, null, 0, 'No ongoing purchase rewards', 'Official issuer material checked 2026-09-28', 'https://www.capitalone.co.uk/creditcards/applying-for-a-credit-card', 'verified', '2026-09-28', 'The promotional duration and transfer fee are personalised (''up to''), so they must not be represented as guaranteed. No ongoing purchase reward is advertised; the non-sterling transaction fee is agreement-specific. 2 introductory or account-specific promotions were recorded in research but excluded from ongoing checkout ranking.', '2026-09-28', '#4d263d', '#9a4d72', '#ffd3e8', true, false),
  ('bff356f6-3679-54b0-8d96-e408ed1c0b62', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'capital-one-classic', 'Capital One Classic Card', 'Capital One (Europe) plc', 'Not stated', 'GB', 'GBP', 'cashback', 0, null, 0, 'No ongoing purchase rewards', 'Official issuer material checked 2026-09-28', 'https://www.capitalone.co.uk/creditcards/credit-builder-credit-cards', 'verified', '2026-09-28', 'Capital One says its UK cards have no annual fee, but the non-sterling transaction fee varies by card agreement. No ongoing purchase reward is advertised on the official product page; model ordinary domestic purchase value as zero rather than inventing a benefit.', '2026-09-28', '#4d263d', '#9a4d72', '#ffd3e8', true, false),
  ('1a4ee766-5b42-537e-ac07-37c6b193d5ca', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'post-office-credit-card', 'Post Office Credit Card', 'Capital One (Europe) plc', 'Mastercard', 'GB', 'GBP', 'cashback', 0, null, 0, 'No ongoing purchase rewards', 'Official issuer material checked 2026-09-28', 'https://www.postoffice.co.uk/credit-card', 'verified', '2026-09-28', 'A Post Office guide mentions up to 12 months, while the live product page retrieved for this review says up to 6 months. Store the personalised issued offer rather than assuming either maximum. No cash-advance fee applies when buying Post Office Travel Money, but that is not a general purchase reward. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking. Published foreign-purchase fee: 2.75%. FX costs are not yet included in ranking.', '2026-09-28', '#4d263d', '#9a4d72', '#ffd3e8', true, false),
  ('fe1df0e5-5696-5adf-9b21-c7a29117c45a', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'post-office-travel-credit-card', 'Post Office Travel Credit Card', 'Capital One (Europe) plc', 'Mastercard', 'GB', 'GBP', 'cashback', 0, null, 0, 'No ongoing purchase rewards', 'Official issuer material checked 2026-09-28', 'https://www.postoffice.co.uk/credit-card/travel-credit-card', 'verified', '2026-09-28', 'Zero foreign transaction fee covers foreign-currency purchases, including online/phone purchases from the UK. A 3% cash advance fee still applies to cash withdrawals or foreign currency bought elsewhere; Post Office Travel Money is the stated exception. 1 introductory or account-specific promotion was recorded in research but excluded from ongoing checkout ranking. Published foreign-purchase fee: 0%. FX costs are not yet included in ranking.', '2026-09-28', '#4d263d', '#9a4d72', '#ffd3e8', true, false),
  ('7d138639-1b60-500c-b7a4-8c97b42aceef', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'halifax-cashback-credit-card', 'Halifax Cashback Credit Card', 'Halifax', 'Not stated', 'GB', 'GBP', 'cashback', 0.25, null, 0, 'Cashback credited to the card account', 'Official issuer material checked 2026-09-28', 'https://www.halifax.co.uk/creditcards/help-guidance/terms-and-conditions.html', 'verified', '2026-09-28', 'Fixed cash value and a single published ongoing rate. Card network is not stated on the product page. Application availability is constrained by the brand migration and should be monitored. Published foreign-purchase fee: 2.95%. FX costs are not yet included in ranking.', '2026-09-28', '#3f311d', '#8c6a32', '#ffe2a1', true, false),
  ('c8c68877-7a6c-554b-95ac-ccc4d302905e', '8a8ecadf-144e-525c-b0bc-24303c52f64a', 'halifax-world-elite-mastercard', 'Halifax World Elite Mastercard®', 'Halifax', 'Mastercard', 'GB', 'GBP', 'cashback', 0, null, 18000, 'Catalogued for identification; reward comparison pending', 'Official issuer material checked 2026-09-28', 'https://www.halifax.co.uk/creditcards/help-guidance/terms-and-conditions.html', 'catalog_only', '2026-09-28', 'Accurate ranking requires the cardholder''s current anniversary-year spend, which the extension does not presently know. Application availability is constrained by the brand migration and should be monitored. Published foreign-purchase fee: 0%. FX costs are not yet included in ranking.', '2026-09-28', '#3f311d', '#8c6a32', '#ffe2a1', true, false),
